    id: crypto.randomUUID(),
    parent,
    type: "Function",
  };
  const fn = baseFn as AST.Function;
  fn.parameters = generateIdentifiers(fn);
  fn.body = generateStatements(fn);

  return fn;
}

export function generateCall(parent: AST.CallParent): AST.Call {
